/**
 * DeepSeek 计费估算：token 用量 → 预估费用（人民币）。
 *
 * 价格来自 DeepSeek 官方（https://api-docs.deepseek.com/zh-cn/quick_start/pricing/），
 * 2026-08-17 00:00（北京时间）起采用峰谷定价：高峰时段 = 北京时间 9:00-12:00、
 * 14:00-18:00，其余为空闲时段；空闲价为高峰价的一半。
 *
 * DeepSeek 的 usage 计费语义（见 llm-deepseek translate）：
 *   - uncachedInputTokens（= inputTokens）= 缓存未命中输入
 *   - cacheReadTokens                         = 缓存命中输入
 *   - outputTokens                            = 输出（推理已含其中）
 *   - cacheWriteTokens                        = DeepSeek 恒为 0（不报告 cache-write）
 * 费用 = 未命中输入 × miss 价 + 缓存命中 × hit 价 + 输出 × output 价。
 */

/** 价格表（元 / 百万 token），key 为模型名。 */
const PRICING = {
  'deepseek-v4-pro': {
    offPeak: { cacheHit: 0.15, miss: 4.5, output: 13.5 },
    peak: { cacheHit: 0.30, miss: 9.0, output: 27.0 },
  },
  'deepseek-v4-flash': {
    offPeak: { cacheHit: 0.05, miss: 1.5, output: 4.5 },
    peak: { cacheHit: 0.10, miss: 3.0, output: 9.0 },
  },
}

/** 默认计费模型。 */
const DEFAULT_MODEL = 'deepseek-v4-pro'

/** 北京时间（UTC+8）当前是否处于高峰时段。 */
export function isPeakHour(now = Date.now()) {
  const h = new Date(now + 8 * 3600000).getUTCHours()
  return (h >= 9 && h < 12) || (h >= 14 && h < 18)
}

/** 安全取值：非负有限数，否则 0。 */
function num(v) {
  return typeof v === 'number' && Number.isFinite(v) && v >= 0 ? v : 0
}

/**
 * 估算本次对话累计费用（元）。
 * @param usage - session projection `tokenUsage` 的值。
 * @returns 预估费用（非负元）。
 */
export function estimateCost(usage) {
  if (usage === undefined || usage === null) return 0
  const tier = isPeakHour() ? PRICING[DEFAULT_MODEL].peak : PRICING[DEFAULT_MODEL].offPeak
  const uncached = (num(usage.uncachedInputTokens) + num(usage.cacheWriteTokens)) / 1e6
  const cached = num(usage.cacheReadTokens) / 1e6
  const output = num(usage.outputTokens) / 1e6
  return uncached * tier.miss + cached * tier.cacheHit + output * tier.output
}

/**
 * 格式化费用：小于 0.01 元保留 4 位小数，否则保留 2 位。
 * @param yuan - 费用（元）。
 * @returns 显示字符串（带 ¥ 前缀）。
 */
export function formatCost(yuan) {
  if (!(yuan > 0)) return '¥0'
  if (yuan < 0.01) return '¥' + yuan.toFixed(4)
  return '¥' + yuan.toFixed(2)
}
